typedef float rational_t;

struct vector3d
{
  rational_t x, y, z;
};

struct wave_marker
{
  rational_t x, y, z;
};

enum
{
  WAVE_MarkerEmitterStartCrestX,
  WAVE_MarkerSurferSpawn,
  WAVE_MarkerLipMark11p45
};

wave_marker *WAVE_GetMarker(int marker);

class entity
{
public:
  const vector3d &get_abs_position() const;
};

class game
{
public:
  int get_beach_id();
};

struct beach_data
{
  bool bdir;
};

extern game *g_game_ptr;
extern beach_data BeachDataArray[];

class kellyslater_controller
{
public:
  entity *get_owner() const;
  rational_t Closest_Tube_Distance();
  int GetWipeoutIntensity(void);
};

enum
{
  WIP_INT_LOW,
  WIP_INT_MED,
  WIP_INT_EXT
};

float g_intensity_height = 5.8f;
float g_intesity2_wip = 0.0f;
int kellyslater_controller::GetWipeoutIntensity(void)
{
	if (g_intesity2_wip)
		return WIP_INT_MED;

	float wave_height = WAVE_GetMarker(WAVE_MarkerEmitterStartCrestX)->y - WAVE_GetMarker(WAVE_MarkerSurferSpawn)->y;
	float wave_x = WAVE_GetMarker(WAVE_MarkerLipMark11p45)->x;
	int current_beach = g_game_ptr->get_beach_id ();
	bool in_boring_region = false;
	bool right = BeachDataArray[current_beach].bdir;
	float tube_dist = Closest_Tube_Distance();
	float x_pos = get_owner()->get_abs_position().x;

	if ((right && (x_pos < wave_x)) || (!right && (x_pos > wave_x)))
		in_boring_region = true;

	if (in_boring_region && (tube_dist > 0.9f))
		return WIP_INT_LOW;
	else if (wave_height > g_intensity_height)
	{
		if (tube_dist < 0.3f)
			return WIP_INT_EXT;

		return WIP_INT_MED;
	}
	else
	{
		if (tube_dist < 0.3f)
			return WIP_INT_MED;

		return WIP_INT_LOW;
	}
}
